    /** A ring of short arcs around the feather icon's dot. */
    private val FEATHER_RING = buildString {
        val arcs = 12
        val r = 8.8f
        for (i in 0 until arcs) {
            val a0 = Math.PI * 2 * i / arcs
            val a1 = a0 + Math.PI * 2 / arcs * 0.55
            append("M${12f + r * kotlin.math.cos(a0).toFloat()} ${12f + r * kotlin.math.sin(a0).toFloat()}")
            append("A$r $r 0 0 1 ${12f + r * kotlin.math.cos(a1).toFloat()} ${12f + r * kotlin.math.sin(a1).toFloat()}")
        }
    }
